"use client";

import React, { useState, useMemo } from "react";
import {
    FileText, UploadCloud, Download, Trash2, Eye, Search, 
    Plus, History, ShieldCheck, Share2, PenTool, FileCheck,
    AlertCircle, Clock, CheckCircle2, MoreVertical, X, Printer
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";
import PageBreadcrumb from "@/components/common/PageBreadCrumb";

/* --- Types --- */
type DocStatus = "Verified" | "Pending" | "Rejected" | "Expiring Soon" | "Signed";

interface DocumentItem {
    id: string;
    name: string;
    category: "Identity" | "Education" | "Company" | "Tax" | "Family";
    size: string;
    uploadDate: string;
    status: DocStatus;
    isSensitiveText?: string;
    version: string;
}

const initialDocs: DocumentItem[] = [
    { id: "1", name: "Passport_Scan.pdf", category: "Identity", size: "2.4 MB", uploadDate: "12 Jan 2026", status: "Expiring Soon", version: "v1.0" },
    { id: "2", name: "Form-16_2025.pdf", category: "Tax", size: "1.1 MB", uploadDate: "05 Jan 2026", status: "Verified", version: "v1.0" },
    { id: "3", name: "NDA_Agreement.pdf", category: "Company", size: "900 KB", uploadDate: "01 Jan 2026", status: "Signed", version: "v2.1" },
    { id: "4", name: "Child_Birth_Cert.pdf", category: "Family", size: "1.5 MB", uploadDate: "08 Jan 2026", status: "Pending", version: "v1.0" },
];

export default function EliteDocumentHub() {
    const [docs, setDocs] = useState<DocumentItem[]>(initialDocs);
    const [activeTab, setActiveTab] = useState("All");
    const [search, setSearch] = useState("");
    
    // UI Logic States
    const [showCertificateModal, setShowCertificateModal] = useState(false);
    const [isSharing, setIsSharing] = useState<DocumentItem | null>(null);

    const filteredDocs = useMemo(() => {
        return docs.filter(doc => {
            const matchesSearch = doc.name.toLowerCase().includes(search.toLowerCase());
            const matchesTab = activeTab === "All" || doc.category === activeTab;
            return matchesSearch && matchesTab;
        });
    }, [search, activeTab, docs]);

    return (
        <div className="p-6 lg:p-10 space-y-8 bg-[#F8F9FB] dark:bg-[#06080F] min-h-screen">
            <PageBreadcrumb pageTitle="Employee Document Vault" />

            {/* 1. COMPLIANCE & ACTION HEADER */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white dark:bg-gray-900 rounded-[2.5rem] p-8 shadow-sm border border-gray-100 dark:border-gray-800 flex justify-between items-center">
                    <div>
                        <div className="flex items-center gap-2 mb-2">
                           <ShieldCheck className="text-emerald-500 w-5 h-5" />
                           <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Compliance Health</span>
                        </div>
                        <h2 className="text-3xl font-black tracking-tighter">92.4% Secure</h2>
                        <p className="text-xs text-gray-500 font-medium mt-1">2 documents require immediate re-verification.</p>
                    </div>
                    <div className="hidden sm:block">
                        <div className="w-24 h-24 rounded-full border-[6px] border-emerald-500/20 border-t-emerald-500 flex items-center justify-center">
                           <span className="text-xl font-black">92%</span>
                        </div>
                    </div>
                </div>

                <div className="bg-brand-600 rounded-[2.5rem] p-8 text-white shadow-xl flex flex-col justify-between group overflow-hidden relative">
                    <Printer className="absolute -right-4 -top-4 w-24 h-24 opacity-10 group-hover:scale-110 transition-transform" />
                    <h3 className="text-xl font-bold relative z-10">Need a Letter?</h3>
                    <p className="text-xs text-brand-100 mb-4 relative z-10">Generate Employment or Salary certificates instantly.</p>
                    <button 
                        onClick={() => setShowCertificateModal(true)}
                        className="bg-white text-brand-600 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest relative z-10 hover:shadow-2xl transition-all"
                    >
                        Generate Certificate
                    </button>
                </div>
            </div>

            {/* 2. ADVANCED TOOLBAR */}
            <div className="bg-white dark:bg-gray-900 rounded-3xl p-4 border border-gray-100 dark:border-gray-800 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                    {["All", "Identity", "Education", "Company", "Tax", "Family"].map(tab => (
                        <button 
                            key={tab} 
                            onClick={() => setActiveTab(tab)}
                            className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                                activeTab === tab ? "bg-brand-500 text-white" : "text-gray-400 hover:text-gray-900"
                            }`}
                        >
                            {tab}
                        </button>
                    ))}
                </div>
                <div className="relative w-full md:w-64 group">
                    <Search className="absolute left-3 top-2.5 text-gray-400 w-4 h-4" />
                    <input 
                        placeholder="Search encrypted vault..." 
                        className="w-full bg-gray-50 dark:bg-gray-800 border-none rounded-xl py-2.5 pl-10 pr-4 text-xs font-bold focus:ring-2 focus:ring-brand-500/50 transition-all"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                    />
                </div>
            </div>

            {/* 3. THE DATA VAULT */}
            <div className="bg-white dark:bg-gray-900 rounded-[3rem] shadow-sm border border-gray-100 dark:border-gray-800 overflow-hidden">
                <table className="w-full text-left">
                    <thead>
                        <tr className="bg-gray-50/50 dark:bg-gray-800/50 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
                            <th className="px-8 py-5">Managed Asset</th>
                            <th className="px-8 py-5">Audit Status</th>
                            <th className="px-8 py-5 text-center">Version</th>
                            <th className="px-8 py-5 text-right">Security Operations</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
                        {filteredDocs.map((doc) => (
                            <tr key={doc.id} className="group hover:bg-gray-50/50 transition-colors">
                                <td className="px-8 py-6">
                                    <div className="flex items-center gap-4">
                                        <div className="w-12 h-12 bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-2xl flex items-center justify-center text-gray-400 group-hover:text-brand-600 transition-colors shadow-sm">
                                            <FileText size={22} />
                                        </div>
                                        <div>
                                            <h4 className="text-sm font-black text-gray-900 dark:text-white">{doc.name}</h4>
                                            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">{doc.category} • {doc.size}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-8 py-6">
                                    <StatusBadge status={doc.status} />
                                </td>
                                <td className="px-8 py-6 text-center">
                                    <span className="text-[10px] font-mono font-bold bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded text-gray-500">{doc.version}</span>
                                </td>
                                <td className="px-8 py-6 text-right space-x-2">
                                    <button onClick={() => setIsSharing(doc)} className="p-2.5 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-xl transition-all" title="Secure Share"><Share2 size={18}/></button>
                                    <button className="p-2.5 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-xl transition-all" title="e-Sign"><PenTool size={18}/></button>
                                    <button className="p-2.5 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-xl transition-all" title="Preview"><Eye size={18}/></button>
                                    <button className="p-2.5 text-gray-400 hover:text-red-500 hover:bg-white dark:hover:bg-gray-800 rounded-xl transition-all" title="Purge"><Trash2 size={18}/></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* --- FUNCTIONAL MODALS --- */}

            {/* A. SECURE SHARE MODAL */}
            {isSharing && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={() => setIsSharing(null)} />
                    <div className="relative bg-white dark:bg-gray-900 rounded-[2.5rem] p-10 w-full max-w-md shadow-2xl animate-in zoom-in-95 duration-200">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-2xl font-black tracking-tighter">Secure Share</h3>
                            <button onClick={() => setIsSharing(null)}><X size={24}/></button>
                        </div>
                        <p className="text-sm text-gray-500 mb-6">Create a time-limited, password-protected link for <span className="font-bold text-gray-900 dark:text-white">"{isSharing.name}"</span>.</p>
                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] font-black uppercase text-gray-400 block mb-2">Recipient Email</label>
                                <input type="email" placeholder="bank@verification.com" className="w-full bg-gray-50 dark:bg-gray-800 border-none rounded-xl p-4 text-sm font-bold" />
                            </div>
                            <div>
                                <label className="text-[10px] font-black uppercase text-gray-400 block mb-2">Expiry</label>
                                <select className="w-full bg-gray-50 dark:bg-gray-800 border-none rounded-xl p-4 text-sm font-bold">
                                    <option>24 Hours</option>
                                    <option>7 Days</option>
                                    <option>One-time View</option>
                                </select>
                            </div>
                        </div>
                        <button className="w-full bg-brand-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest text-[10px] mt-8 shadow-xl shadow-brand-500/20">Generate Secure Link</button>
                    </div>
                </div>
            )}

            {/* B. CERTIFICATE GENERATION MODAL */}
            {showCertificateModal && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={() => setShowCertificateModal(false)} />
                    <div className="relative bg-white dark:bg-gray-900 rounded-[2.5rem] p-10 w-full max-w-lg shadow-2xl animate-in zoom-in-95 duration-200">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-2xl font-black tracking-tighter">Self-Service Issuance</h3>
                            <button onClick={() => setShowCertificateModal(false)}><X size={24}/></button>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <CertTypeCard title="Employment" desc="Proof of current status" />
                            <CertTypeCard title="Salary" desc="For Bank Loans/KYC" />
                            <CertTypeCard title="Bonafide" desc="For Education/Visa" />
                            <CertTypeCard title="Relieving" desc="Available after notice" disabled />
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

/* --- REUSABLE PIECES --- */

const CertTypeCard = ({ title, desc, disabled = false }: any) => (
    <button disabled={disabled} className={`p-6 border text-left rounded-3xl transition-all ${disabled ? 'opacity-40 grayscale cursor-not-allowed' : 'hover:border-brand-500 hover:bg-brand-50/50'}`}>
        <FileCheck className="text-brand-600 mb-3" size={24} />
        <h4 className="text-sm font-black">{title}</h4>
        <p className="text-[10px] text-gray-400 font-bold mt-1">{desc}</p>
    </button>
);

const StatusBadge = ({ status }: { status: DocStatus }) => {
    const variants: any = {
        Verified: "bg-emerald-50 text-emerald-600 border-emerald-100",
        Pending: "bg-amber-50 text-amber-600 border-amber-100",
        Signed: "bg-blue-50 text-blue-600 border-blue-100",
        "Expiring Soon": "bg-red-50 text-red-600 border-red-100 animate-pulse",
    };
    return (
        <span className={`px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-[0.1em] border ${variants[status]}`}>
            {status}
        </span>
    );
};